/* Generated by port_site.py from the approved mockup. Behaviour for the stays section; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce,
    root = document.documentElement;

  /* section 7: a deck of cards. The front card plays its moment while its pill fills, then drops away and the next comes forward. Pills, a tap on a back card, a swipe or the arrow keys pick one and stop the roll. */
  (function () {
    var sec = document.getElementById("stays"),
      deck = document.getElementById("cards7"),
      cards = [].slice.call(deck.querySelectorAll(".pc")),
      pills = [].slice.call(document.querySelectorAll("#pills7 .pill7")),
      bar = document.getElementById("pills7"),
      order = cards.map(function (_, k) {
        return k;
      }),
      touched = false,
      started = false,
      timers = [],
      dropT = 0;
    function layout() {
      order.forEach(function (ci, slot) {
        cards[ci].setAttribute("data-s", Math.min(slot, 3));
        cards[ci].setAttribute("aria-hidden", slot ? "true" : "false");
      });
    }
    function clear() {
      timers.forEach(clearTimeout);
      timers = [];
    }
    function play() {
      var j = order[0];
      clear();
      cards.forEach(function (c, k) {
        if (k !== j) c.classList.remove("prep");
      });
      pills.forEach(function (p, k) {
        p.classList.toggle("on", k === j);
        p.setAttribute("aria-selected", k === j ? "true" : "false");
        p.classList.remove("run");
      });
      var pl = pills[j];
      if (bar.scrollWidth > bar.clientWidth)
        bar.scrollTo({
          left: pl.offsetLeft - bar.clientWidth / 2 + pl.offsetWidth / 2,
          behavior: reduce ? "auto" : "smooth",
        });
      if (!touched && !reduce) {
        void pl.offsetWidth;
        pl.classList.add("run");
      }
      if (reduce) return;
      var c = cards[j],
        ms = [].slice.call(c.querySelectorAll(".m7")),
        at = 380;
      c.classList.add("prep");
      ms.forEach(function (m) {
        m.classList.remove("in", "typing");
      });
      ms.forEach(function (m) {
        if (m.classList.contains("hb7")) {
          timers.push(
            ctx.setTimeout(function () {
              m.classList.add("in", "typing");
            }, at),
          );
          at += 820;
          timers.push(
            ctx.setTimeout(function () {
              m.classList.remove("typing");
            }, at),
          );
        } else
          timers.push(
            ctx.setTimeout(function () {
              m.classList.add("in");
            }, at),
          );
        at += 480;
      });
    }
    function next() {
      var f = cards[order[0]];
      if (!reduce) {
        ctx.clearTimeout(dropT);
        f.classList.add("drop");
        dropT = ctx.setTimeout(function () {
          f.classList.remove("drop");
        }, 620);
      }
      order.push(order.shift());
      layout();
      play();
    }
    function prev() {
      order.unshift(order.pop());
      layout();
      play();
    }
    function bring(j) {
      if (order[0] === j) return;
      while (order[0] !== j) order.push(order.shift());
      layout();
      play();
    }
    function stop() {
      if (touched) return;
      touched = true;
      sec.classList.add("stopped");
      pills.forEach(function (p) {
        p.classList.remove("run");
      });
    }
    pills.forEach(function (p, k) {
      ctx.on(p, "click", function () {
        stop();
        bring(k);
      });
    });
    cards.forEach(function (c, k) {
      ctx.on(c, "click", function () {
        if (order[0] !== k) {
          stop();
          bring(k);
        }
      });
    });
    pills.forEach(function (p) {
      ctx.on(p.querySelector("i"), "animationend", function () {
        if (!touched && p.classList.contains("on")) next();
      });
    });
    var x0 = null;
    ctx.on(
      deck,
      "pointerdown",
      function (e) {
        x0 = e.clientX;
      },
      { passive: true },
    );
    ctx.on(
      deck,
      "pointerup",
      function (e) {
        if (x0 === null) return;
        var dx = e.clientX - x0;
        x0 = null;
        if (Math.abs(dx) > 40) {
          stop();
          if (dx < 0) next();
          else prev();
        }
      },
      { passive: true },
    );
    ctx.on(deck, "keydown", function (e) {
      if (e.key === "ArrowRight") {
        stop();
        next();
      } else if (e.key === "ArrowLeft") {
        stop();
        prev();
      }
    });
    ctx.on(deck, "mouseenter", function () {
      sec.classList.add("hold");
    });
    ctx.on(deck, "mouseleave", function () {
      sec.classList.remove("hold");
    });
    layout();
    function vis(on) {
      sec.classList.toggle("off", !on);
      if (on && !started) {
        started = true;
        play();
      }
    }
    if ("IntersectionObserver" in window)
      ctx
        .io(
          function (es) {
            vis(es[0].isIntersecting);
          },
          { threshold: 0.35 },
        )
        .observe(deck);
    else vis(true);
  })();
}
